		Rating14.value,
		Rating15.value,
    Rating16.value,
		Rating17.value
  ];

  const hasInvalidRating = ratings.some(r => r === null || r === 0);

  if (hasInvalidRating) {
    return "OBIETTIVO DELLA SETTIMANA: ATTITUDINE ALLA VENDITA";
  }

  const somma = ratings.reduce((acc, val) => acc + val, 0);

  return somma === 51
